def length_of_lis(nums):
    n = len(nums)

    def f(i, prev):            # best from nums[i:], last taken index prev
        if i == n:
            return 0
        best = f(i + 1, prev)
        if prev == -1 or nums[prev] < nums[i]:
            best = max(best, 1 + f(i + 1, i))
        return best
    return f(0, -1)

