def length_of_lis(nums):
    n = len(nums)
    dp = [[0] * (n + 1) for _ in range(n + 1)]     # dp[i][prev + 1]
    for i in range(n - 1, -1, -1):
        for prev in range(i - 1, -2, -1):
            best = dp[i + 1][prev + 1]
            if prev == -1 or nums[prev] < nums[i]:
                best = max(best, 1 + dp[i + 1][i + 1])
            dp[i][prev + 1] = best
    return dp[0][0]

def length_of_lis(nums):
    n = len(nums)
    nxt = [0] * (n + 1)        # row i+1
    for i in range(n - 1, -1, -1):
        cur = [0] * (n + 1)
        for prev in range(i - 1, -2, -1):
            best = nxt[prev + 1]
            if prev == -1 or nums[prev] < nums[i]:
                best = max(best, 1 + nxt[i + 1])
            cur[prev + 1] = best
        nxt = cur
    return nxt[0]

def length_of_lis(nums):
    n = len(nums)
    row = [0] * (n + 1)        # row[prev + 1] = f(i + 1, prev)
    for i in range(n - 1, -1, -1):
        take = 1 + row[i + 1]  # f(i+1, i): not written in this pass
        for prev in range(i - 1, -2, -1):
            if prev == -1 or nums[prev] < nums[i]:
                row[prev + 1] = max(row[prev + 1], take)
    return row[0]

def length_of_lis(nums):
    dp = [1] * len(nums)
    for i in range(len(nums)):
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
    return max(dp)

def length_of_lis(nums):
    tails = []
    for x in nums:
        k = bisect.bisect_left(tails, x)
        if k == len(tails):
            tails.append(x)
        else:
            tails[k] = x
    return len(tails)
